"""Checks the committed icon resources (generated by scripts/make_icons.py). Needs pillow + numpy."""
import unittest
import xml.etree.ElementTree as ET
from pathlib import Path

try:
    import numpy as np
    from PIL import Image
except ImportError:  # CI installs these; locally the tests are skipped with a visible reason
    np = Image = None

RES = Path(__file__).resolve().parents[2] / "app/src/main/res"
DENS = {"mdpi": 1.0, "hdpi": 1.5, "xhdpi": 2.0, "xxhdpi": 3.0, "xxxhdpi": 4.0}


@unittest.skipIf(Image is None, "pillow/numpy not installed")
class IconTests(unittest.TestCase):
    def test_foreground_stays_inside_adaptive_safe_circle(self):
        for name, d in DENS.items():
            im = Image.open(RES / f"mipmap-{name}/ic_launcher_foreground.png")
            self.assertEqual(im.size, (round(108 * d), round(108 * d)))
            alpha = np.array(im.getchannel("A"))
            ys, xs = np.where(alpha > 50)
            self.assertGreater(len(xs), 100, name)
            r = np.sqrt((xs + 0.5 - im.width / 2) ** 2 + (ys + 0.5 - im.height / 2) ** 2).max()
            self.assertLessEqual(r, 33 * d + 1.0, f"{name}: artwork leaves the 66dp safe circle (r={r:.1f})")

    def test_monochrome_is_single_colour(self):
        for name in DENS:
            a = np.array(Image.open(RES / f"mipmap-{name}/ic_launcher_monochrome.png").convert("RGBA"))
            visible = a[a[..., 3] > 0][:, :3]
            self.assertTrue((visible == 0).all(), name)

    def test_status_bar_icon_is_white_and_24dp(self):
        for name, d in DENS.items():
            im = Image.open(RES / f"drawable-{name}/ic_stat_viddown.png").convert("RGBA")
            self.assertEqual(im.size, (round(24 * d), round(24 * d)))
            a = np.array(im)
            visible = a[a[..., 3] > 0][:, :3]
            self.assertGreater(len(visible), 10, name)
            self.assertTrue((visible == 255).all(), name)

    def test_legacy_icons_exist_with_48dp_size(self):
        for name, d in DENS.items():
            for f in ("ic_launcher.png", "ic_launcher_round.png"):
                self.assertEqual(Image.open(RES / f"mipmap-{name}/{f}").size, (round(48 * d), round(48 * d)))

    def test_adaptive_xml_references_exist(self):
        for f in ("ic_launcher.xml", "ic_launcher_round.xml"):
            root = ET.parse(RES / "mipmap-anydpi-v26" / f).getroot()
            self.assertEqual(root.tag, "adaptive-icon")
            self.assertEqual({c.tag for c in root}, {"background", "foreground", "monochrome"})
        colors = ET.parse(RES / "values/ic_launcher_background.xml").getroot()
        self.assertEqual(colors[0].get("name"), "ic_launcher_background")

    def test_logo_is_transparent(self):
        im = Image.open(RES / "drawable-nodpi/viddown_logo.png")
        self.assertEqual(im.mode, "RGBA")
        self.assertEqual(im.getpixel((0, 0))[3], 0)


if __name__ == "__main__":
    unittest.main()
